#if PROFILE_UNLOCK_TESTING
using System.IO;
using System.IO.Compression;
using System.Text.Json;

namespace FH6LocalCryptoTool;

// Installed FH6 definitions and English strings, inspected 2026-10-14.
// Generated from strictly round-tripped definitions; no save/account data.
internal static class ProfileInventoryNames
{
    sealed record NameRow(string Kind, ulong Id, string Name);
    static readonly Dictionary<(string, ulong), string> Names = Decode().ToDictionary(n => (n.Kind, n.Id), n => n.Name);
    public static string Get(string kind, ulong id, string fallback) => kind == "Clothes" && id == 0x2058CE8305197A72UL
        ? "7-Eleven Uniform" // Confirmed by the owner's natural reward screenshot; missing from the older English string table.
        : Names.GetValueOrDefault((kind, id)) ?? Humanize(fallback);
    static string Humanize(string text) => System.Text.RegularExpressions.Regex.Replace(text.Replace("Horn_SFX_", "").Replace("Horn_Musical_", "").Replace("Horn_Standard_", "").Replace("Emote_", "").Replace('_', ' '), "(?<=[a-z])(?=[A-Z])", " ");
    static NameRow[] Decode()
    {
        using var input = new MemoryStream(Convert.FromBase64String(Encoded));
        using var gzip = new GZipStream(input, CompressionMode.Decompress);
        return JsonSerializer.Deserialize<NameRow[]>(gzip) ?? throw new InvalidDataException("Inventory catalog is missing.");
    }
    const string Encoded = "";
}
#endif

